contracts/BlacklistableUpgradeable.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { AccessControlEnumerableUpgradeable } from "@openzeppelin/contracts-upgradeable/access/extensions/AccessControlEnumerableUpgradeable.sol";
import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

/**
 * @title BlacklistableUpgradeable
 * @notice Provides blacklist functionality for token contracts
 * @dev Implements address blacklisting to enable regulatory compliance and incident response.
 *      Use cases include freezing stolen funds, complying with legal requirements, or
 *      preventing compromised addresses from interacting with the token.
 */
abstract contract BlacklistableUpgradeable is Initializable, AccessControlEnumerableUpgradeable {
    bytes32 public constant BLACKLISTER_ROLE = keccak256("BLACKLISTER_ROLE");
    bytes32 public constant BLACKLISTER_ROLE_ADMIN = keccak256("BLACKLISTER_ROLE_ADMIN");

    /***************************************************
     *                   STORAGE                       *
     ***************************************************/

    /// @custom:storage-location erc7201:camino.network.BridgedCamino.blacklistable
    struct BlacklistableStorage {
        mapping(address => bool) blacklisted;
    }

    // ERC-7201 namespaced storage pattern prevents storage collisions during upgrades
    // keccak256(abi.encode(uint256(keccak256("camino.network.BridgedCaminoV1.blacklistable")) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant BlacklistableStorageLocation =
        0x68774384eeaf242da1643f15db6daf1574e4e74409b3ab6ed48adc9617047100;

    function _getBlacklistableStorage() internal pure returns (BlacklistableStorage storage $) {
        assembly {
            $.slot := BlacklistableStorageLocation
        }
    }

    /***************************************************
     *                     INIT                        *
     ***************************************************/

    function __Blacklistable_init() internal onlyInitializing {
        _setRoleAdmin(BLACKLISTER_ROLE, BLACKLISTER_ROLE_ADMIN);
    }

    /***************************************************
     *                    EVENTS                       *
     ***************************************************/

    event Blacklisted(address indexed _account);
    event UnBlacklisted(address indexed _account);

    /***************************************************
     *                    ERRORS                       *
     ***************************************************/

    error AccountIsBlacklisted(address _account);

    /***************************************************
     *                  MODIFIERS                      *
     ***************************************************/

    modifier notBlacklisted(address _account) {
        if (_isBlacklisted(_account)) {
            revert AccountIsBlacklisted(_account);
        }
        _;
    }

    /***************************************************
     *                    FUNCS                        *
     ***************************************************/

    function isBlacklisted(address _account) external view returns (bool) {
        return _isBlacklisted(_account);
    }

    /**
     * @notice Adds an address to the blacklist
     * @dev Use this for regulatory compliance, freezing stolen funds, or blocking compromised addresses.
     *      Blacklisted addresses cannot transfer, receive, or approve tokens.
     * @param _account The address to blacklist
     */
    function blacklist(address _account) external onlyRole(BLACKLISTER_ROLE) {
        _blacklist(_account);
        emit Blacklisted(_account);
    }

    /**
     * @notice Removes an address from the blacklist
     * @dev Use this to restore access after legal resolution or when address is no longer a threat.
     * @param _account The address to remove from blacklist
     */
    function unBlacklist(address _account) external onlyRole(BLACKLISTER_ROLE) {
        _unBlacklist(_account);
        emit UnBlacklisted(_account);
    }

    function _isBlacklisted(address _account) internal view virtual returns (bool) {
        return _getBlacklistableStorage().blacklisted[_account];
    }

    function _blacklist(address _account) internal virtual {
        _getBlacklistableStorage().blacklisted[_account] = true;
    }

    function _unBlacklist(address _account) internal virtual {
        _getBlacklistableStorage().blacklisted[_account] = false;
    }
}

contracts/BridgedCaminoV1.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
// Compatible with OpenZeppelin Contracts ^5.0.0
pragma solidity 0.8.28;

import { AccessControlEnumerableUpgradeable } from "@openzeppelin/contracts-upgradeable/access/extensions/AccessControlEnumerableUpgradeable.sol";
import { ERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import { ERC20BurnableUpgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20BurnableUpgradeable.sol";
import { ERC20PausableUpgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PausableUpgradeable.sol";
import { ERC20PermitUpgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC20PermitUpgradeable.sol";
import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { UUPSUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import { BlacklistableUpgradeable } from "./BlacklistableUpgradeable.sol";

/**
 * @title BridgedCamino
 * @notice A bridged wrapped token for Camino network with controlled minting and emergency controls.
 * @dev This contract implements a secure bridging pattern where:
 *      - Minting is restricted to authorized bridges with individual allowance quotas to limit blast radius
 *      - Burning is restricted to bridges to ensure proper cross-chain reconciliation
 *      - Pausability provides emergency stop mechanism for security incidents
 *      - Blacklisting enables regulatory compliance and recovery from compromised addresses
 *      - UUPS upgradeability allows bug fixes while maintaining the same proxy address
 */
contract BridgedCaminoV1 is
    Initializable,
    ERC20Upgradeable,
    ERC20BurnableUpgradeable,
    ERC20PausableUpgradeable,
    AccessControlEnumerableUpgradeable,
    ERC20PermitUpgradeable,
    BlacklistableUpgradeable,
    UUPSUpgradeable
{
    // Role separation ensures that different operational concerns can be managed independently
    // with appropriate privilege levels, following principle of least privilege
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant PAUSER_ROLE_ADMIN = keccak256("PAUSER_ROLE_ADMIN");
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant MINTER_ROLE_ADMIN = keccak256("MINTER_ROLE_ADMIN");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");
    bytes32 public constant UPGRADER_ROLE_ADMIN = keccak256("UPGRADER_ROLE_ADMIN");

    /***************************************************
     *                   STORAGE                       *
     ***************************************************/

    /// @custom:storage-location erc7201:camino.network.BridgedCaminoV1
    struct BridgedCaminoV1Storage {
        // Each minter has an individual allowance to limit damage if a bridge is compromised
        // This implements the same security pattern as USDC's FiatToken
        mapping(address minter => uint256 allowance) minterAllowance;
    }

    // keccak256(abi.encode(uint256(keccak256("camino.network.BridgedCaminoV1")) - 1)) & ~bytes32(uint256(0xff));
    bytes32 private constant BridgedCaminoV1StorageLocation =
        0x182ef02838af5b5b479414017cf218d6b9338a983918bfae3ca63eb3174f1500;

    function _getBridgedCaminoV1Storage() internal pure returns (BridgedCaminoV1Storage storage $) {
        assembly {
            $.slot := BridgedCaminoV1StorageLocation
        }
    }

    /***************************************************
     *                    EVENTS                       *
     ***************************************************/

    /**
     * @notice Emitted when a minter mints `amount` tokens to `to`
     * @param minter The address of the minter
     * @param to The address of the recipient
     * @param amount The amount of tokens minted
     */
    event Mint(address indexed minter, address indexed to, uint256 amount);

    /**
     * @notice Emitted when a minter burns `amount` tokens from `from`
     * @param minter The address of the minter
     * @param from The address of the burner
     * @param amount The amount of tokens burned
     */
    event Burn(address indexed minter, address indexed from, uint256 amount);

    /**
     * @notice Emitted when a minter is configured
     * @param minter The address of the minter
     * @param allowance The allowance of the minter
     * @param newMinter Whether the minter is new or not
     */
    event MinterConfigured(address indexed minter, uint256 allowance, bool newMinter);

    /**
     * @notice Emitted when a minter is removed
     * @param minter The address of the minter
     */
    event MinterRemoved(address indexed minter);

    /***************************************************
     *                    ERRORS                       *
     ***************************************************/

    /**
     * @notice Thrown when the mint amount exceeds the minter's allowance
     * @param _minter The address of the minter
     * @param _amount The amount attempted to mint
     */
    error AmountExceedsMintAllowance(address _minter, uint256 _amount);

    /***************************************************
     *                     INIT                        *
     ***************************************************/

    /**
     * @notice Initialization parameters for BridgedCamino
     * @param name Token name (e.g., "Bridged Camino")
     * @param symbol Token symbol (e.g., "bCAM")
     * @param defaultAdmin Address that receives DEFAULT_ADMIN_ROLE (controls all role admins)
     * @param pauser Address that receives PAUSER_ROLE (can pause/unpause)
     * @param upgrader Address that receives UPGRADER_ROLE (can upgrade contract)
     * @param blacklister Address that receives BLACKLISTER_ROLE (can blacklist addresses)
     * @param pauserRoleAdmin Address that receives PAUSER_ROLE_ADMIN (manages pausers)
     * @param upgraderRoleAdmin Address that receives UPGRADER_ROLE_ADMIN (manages upgraders)
     * @param minterRoleAdmin Address that receives MINTER_ROLE_ADMIN (manages minters)
     * @param blacklisterRoleAdmin Address that receives BLACKLISTER_ROLE_ADMIN (manages blacklisters)
     */
    struct InitParams {
        string name;
        string symbol;
        address defaultAdmin;
        address pauser;
        address upgrader;
        address blacklister;
        address pauserRoleAdmin;
        address upgraderRoleAdmin;
        address minterRoleAdmin;
        address blacklisterRoleAdmin;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initializes the BridgedCamino token with all roles and admins
     * @param params Struct containing all initialization parameters
     */
    function initialize(InitParams calldata params) public initializer {
        __ERC20_init(params.name, params.symbol);
        __ERC20Burnable_init();
        __ERC20Pausable_init();
        __AccessControl_init();
        __ERC20Permit_init(params.name);
        __UUPSUpgradeable_init();
        __Blacklistable_init();

        // Grant roles
        _grantRole(DEFAULT_ADMIN_ROLE, params.defaultAdmin);
        _grantRole(PAUSER_ROLE, params.pauser);
        _grantRole(UPGRADER_ROLE, params.upgrader);
        _grantRole(BLACKLISTER_ROLE, params.blacklister);

        // Grant admin roles
        _grantRole(PAUSER_ROLE_ADMIN, params.pauserRoleAdmin);
        _grantRole(UPGRADER_ROLE_ADMIN, params.upgraderRoleAdmin);
        _grantRole(MINTER_ROLE_ADMIN, params.minterRoleAdmin);
        _grantRole(BLACKLISTER_ROLE_ADMIN, params.blacklisterRoleAdmin);

        // Set role admins
        _setRoleAdmin(PAUSER_ROLE, PAUSER_ROLE_ADMIN);
        _setRoleAdmin(MINTER_ROLE, MINTER_ROLE_ADMIN);
        _setRoleAdmin(UPGRADER_ROLE, UPGRADER_ROLE_ADMIN);
        // This is already set in __Blacklistable_init(), but we set it here
        // explicitly for consistency
        _setRoleAdmin(BLACKLISTER_ROLE, BLACKLISTER_ROLE_ADMIN);
    }

    /***************************************************
     *                     MINT                        *
     ***************************************************/

    /**
     * @notice Mints tokens from the caller's minting allowance quota
     * @dev Restricted to MINTER_ROLE (typically bridge contracts). The allowance system ensures
     *      that if a single bridge is compromised, damage is limited to that bridge's quota.
     *      Reverts if paused to prevent minting during security incidents.
     * @param to The address of the recipient
     * @param amount The amount of tokens to mint
     */
    function mint(address to, uint256 amount) external virtual whenNotPaused onlyRole(MINTER_ROLE) {
        BridgedCaminoV1Storage storage $ = _getBridgedCaminoV1Storage();

        uint256 minterAllowanceAmount = $.minterAllowance[msg.sender];

        if (minterAllowanceAmount < amount) {
            revert AmountExceedsMintAllowance(msg.sender, amount);
        }

        $.minterAllowance[msg.sender] = minterAllowanceAmount - amount;

        emit Mint(msg.sender, to, amount);

        _mint(to, amount);
    }

    /**
     * @notice Returns the remaining minting quota for a given minter
     * @dev Use this to monitor bridge allowances and detect when they need to be increased
     * @param minter The address of the minter
     * @return amount The remaining allowance of the minter
     */
    function minterAllowance(address minter) external view virtual returns (uint256 amount) {
        BridgedCaminoV1Storage storage $ = _getBridgedCaminoV1Storage();
        return $.minterAllowance[minter];
    }

    /**
     * @notice Checks if an address is a minter
     * @dev Returns true if the address has the MINTER_ROLE
     * @param account The address to check
     * @return True if the address is a minter, false otherwise
     */
    function isMinter(address account) external view virtual returns (bool) {
        return hasRole(MINTER_ROLE, account);
    }

    /**
     * @notice Grants MINTER_ROLE to an address and sets/updates their minting allowance quota
     * @dev Used to onboard new bridges or adjust existing bridge quotas. Setting allowance to a lower
     *      value can be used to gradually phase out a bridge. Reverts if paused to prevent
     *      configuration changes during incident investigation.
     * @param minter The address of the minter
     * @param minterAllowanceAmount The new total allowance for the minter (not incremental)
     */
    function configureMinter(
        address minter,
        uint256 minterAllowanceAmount
    ) external whenNotPaused onlyRole(MINTER_ROLE_ADMIN) {
        BridgedCaminoV1Storage storage $ = _getBridgedCaminoV1Storage();

        // Grant minter role
        bool granted = _grantRole(MINTER_ROLE, minter);

        // Set minter allowance
        $.minterAllowance[minter] = minterAllowanceAmount;

        // Emit event
        emit MinterConfigured(minter, minterAllowanceAmount, granted);
    }

    /**
     * @notice Removes minting privileges from an address
     * @dev Use this to decommission bridges or revoke access from compromised addresses.
     *      Can be called even when paused to allow emergency response.
     * @param minter The address of the minter to remove
     */
    function removeMinter(address minter) external virtual onlyRole(MINTER_ROLE_ADMIN) {
        BridgedCaminoV1Storage storage $ = _getBridgedCaminoV1Storage();

        // Revoke minter role
        _revokeRole(MINTER_ROLE, minter);

        // Remove minter allowance
        $.minterAllowance[minter] = 0;

        // Emit event
        emit MinterRemoved(minter);
    }

    /***************************************************
     *                     BURN                        *
     ***************************************************/

    /**
     * @notice Burns tokens from the caller's balance
     * @dev Restricted to MINTER_ROLE to ensure only bridges burn tokens during unlock operations,
     *      maintaining proper cross-chain accounting. Can be called when paused to allow
     *      emergency supply reduction during security incidents (following USDC pattern).
     * @param amount The amount of tokens to burn
     */
    function burn(uint256 amount) public virtual override onlyRole(MINTER_ROLE) {
        emit Burn(msg.sender, msg.sender, amount);
        super.burn(amount);
    }

    /**
     * @notice Burns tokens from a specified address (requires prior approval)
     * @dev Restricted to MINTER_ROLE for cross-chain accounting. Can be called when paused
     *      to enable emergency response scenarios like burning tokens from compromised addresses.
     * @param from The address from which to burn tokens
     * @param amount The amount of tokens to burn
     */
    function burnFrom(address from, uint256 amount) public virtual override onlyRole(MINTER_ROLE) {
        emit Burn(msg.sender, from, amount);
        super.burnFrom(from, amount);
    }

    /***************************************************
     *                    PAUSER                       *
     ***************************************************/

    /**
     * @notice Activates emergency stop, preventing mints and transfers
     * @dev Use this immediately upon detecting a security incident. Pausing stops new supply
     *      creation and token movement while allowing burns for incident remediation.
     */
    function pause() public virtual onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @notice Deactivates emergency stop, resuming normal operations
     * @dev Use this after security incident is resolved and contract state is verified as safe.
     */
    function unpause() public virtual onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /***************************************************
     *                  UPGRADE AUTH                   *
     ***************************************************/

    /**
     * @notice Authorizes upgrading the contract implementation
     * @dev UUPS upgrade authorization. Restricted to UPGRADER_ROLE to ensure only authorized
     *      governance can deploy new logic while maintaining the same proxy address.
     * @param newImplementation The address of the new implementation contract
     */
    function _authorizeUpgrade(address newImplementation) internal virtual override onlyRole(UPGRADER_ROLE) {}

    /***************************************************
     *                 BLACKLIST AUTH                  *
     ***************************************************/

    /**
     * @dev Overrides ERC20 approve to add blacklist checks
     *      Checks msg.sender to prevent blacklisted users from granting approvals via permit or other mechanisms.
     *      Checks owner and spender to prevent blacklisted addresses from participating in the approval system.
     * @param owner The address of the token owner
     * @param spender The address of the spender
     * @param value The amount of tokens to approve
     * @param emitEvent Whether to emit the Approval event
     */
    function _approve(
        address owner,
        address spender,
        uint256 value,
        bool emitEvent
    )
        internal
        virtual
        override(ERC20Upgradeable)
        notBlacklisted(owner)
        notBlacklisted(spender)
        notBlacklisted(msg.sender)
    {
        super._approve(owner, spender, value, emitEvent);
    }

    /**
     * @dev Overrides ERC20 update to add blacklist and pause checks
     *      Checks msg.sender in addition to from/to to prevent blacklisted addresses from
     *      moving tokens via third-party mechanisms like transferFrom or contract interactions.
     *      Allows burning even when paused (to == address(0)) to enable emergency supply reduction.
     * @param from The address of the sender (address(0) for minting)
     * @param to The address of the recipient (address(0) for burning)
     * @param value The amount of tokens to transfer
     */
    function _update(
        address from,
        address to,
        uint256 value
    )
        internal
        virtual
        override(ERC20Upgradeable, ERC20PausableUpgradeable)
        notBlacklisted(from)
        notBlacklisted(to)
        notBlacklisted(msg.sender)
    {
        // Allow burning even when paused for emergency supply reduction
        // For all other operations (mint, transfer), enforce pause check
        if (to != address(0)) {
            _requireNotPaused();
        }

        // Call ERC20Upgradeable._update directly to bypass ERC20PausableUpgradeable's pause check
        // since we're handling pause logic manually above
        ERC20Upgradeable._update(from, to, value);
    }
}

contracts/interfaces/IMinterManagement.s.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

/**
 * @title IMinterManagement
 * @notice Interface for contracts that manage minters and their allowances
 * @dev A contract that implements this interface has external functions for adding and removing
 *      minters and modifying their allowances. This is compatible with USDC's MinterManagementInterface
 *      but modernized for Solidity ^0.8.0
 */
interface IMinterManagement {
    /**
     * @notice Checks if an address is a minter
     * @param account The address to check
     * @return True if the address is a minter, false otherwise
     */
    function isMinter(address account) external view returns (bool);

    /**
     * @notice Returns the remaining minting quota for a given minter
     * @param minter The address of the minter
     * @return The remaining allowance of the minter
     */
    function minterAllowance(address minter) external view returns (uint256);

    /**
     * @notice Grants minter role to an address and sets their minting allowance
     * @param minter The address of the minter
     * @param minterAllowedAmount The minting allowance to set
     */
    function configureMinter(address minter, uint256 minterAllowedAmount) external;

    /**
     * @notice Removes minter role from an address
     * @param minter The address of the minter to remove
     */
    function removeMinter(address minter) external;
}

contracts/minting/Controller.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { EnumerableMap } from "@openzeppelin/contracts/utils/structs/EnumerableMap.sol";

/**
 * @title Controller
 * @notice Generic implementation of the owner-controller-worker model
 * @dev One owner manages many controllers. Each controller manages one worker.
 *      Workers may be reused across different controllers.
 *      This is a modernized version of USDC's Controller contract using custom errors.
 */
contract Controller is Ownable {
    using EnumerableMap for EnumerableMap.AddressToAddressMap;

    /***************************************************
     *                   STORAGE                       *
     ***************************************************/

    /**
     * @dev A controller manages a single worker address.
     * controllers[controller] = worker
     */
    EnumerableMap.AddressToAddressMap private controllers;

    /***************************************************
     *                    EVENTS                       *
     ***************************************************/

    /**
     * @notice Emitted when a controller is configured with a worker
     * @param controller The address of the controller
     * @param worker The address of the worker
     */
    event ControllerConfigured(address indexed controller, address indexed worker);

    /**
     * @notice Emitted when a controller is removed
     * @param controller The address of the controller
     */
    event ControllerRemoved(address indexed controller);

    /***************************************************
     *                    ERRORS                       *
     ***************************************************/

    /**
     * @notice Thrown when a non-controller address attempts a controller-only action
     * @param caller The address that attempted the action
     */
    error NotController(address caller);

    /**
     * @notice Thrown when attempting to configure a controller with a zero address
     */
    error ControllerZeroAddress();

    /**
     * @notice Thrown when attempting to configure a worker with a zero address
     */
    error WorkerZeroAddress();

    /**
     * @notice Thrown when attempting to remove a controller that doesn't exist
     * @param controller The controller address that doesn't exist
     */
    error ControllerNotFound(address controller);

    /***************************************************
     *                  MODIFIERS                      *
     ***************************************************/

    /**
     * @notice Ensures that caller is a controller with a non-zero worker address
     */
    modifier onlyController() {
        if (!controllers.contains(msg.sender)) {
            revert NotController(msg.sender);
        }
        _;
    }

    /***************************************************
     *                CONSTRUCTOR                      *
     ***************************************************/

    constructor(address owner) Ownable(owner) {}

    /***************************************************
     *              VIEW FUNCTIONS                     *
     ***************************************************/

    /**
     * @notice Gets the worker address managed by a controller
     * @param controller The controller address
     * @return The worker address (address(0) if controller not configured)
     */
    function getWorker(address controller) external view returns (address) {
        return _getWorker(controller);
    }

    /**
     * @dev Internal function to get the worker address for a controller
     * @param controller The controller address
     * @return The worker address (address(0) if controller not configured)
     */
    function _getWorker(address controller) internal view returns (address) {
        (, address worker) = controllers.tryGet(controller);
        return worker;
    }

    /**
     * @notice Gets the total number of configured controllers
     * @return The count of controllers
     */
    function getControllerCount() external view returns (uint256) {
        return controllers.length();
    }

    /**
     * @notice Gets the controller and worker at a specific index
     * @param index The index to query
     * @return controller The controller address at the given index
     * @return worker The worker address associated with the controller
     */
    function getControllerAt(uint256 index) external view returns (address controller, address worker) {
        return controllers.at(index);
    }

    /**
     * @notice Gets all controllers and their associated workers
     * @dev This function returns an array of all controllers and their associated
       workers. Thus it is possible to run out of gas if there are too many
       controllers. This assumes that there are not too many controllers.
     * @return controllerAddresses Array of all controller addresses
     * @return workerAddresses Array of all worker addresses
     */
    function getAllControllers()
        external
        view
        returns (address[] memory controllerAddresses, address[] memory workerAddresses)
    {
        uint256 length = controllers.length();
        controllerAddresses = new address[](length);
        workerAddresses = new address[](length);

        for (uint256 i = 0; i < length; i++) {
            (controllerAddresses[i], workerAddresses[i]) = controllers.at(i);
        }

        return (controllerAddresses, workerAddresses);
    }

    /***************************************************
     *           ONLY OWNER FUNCTIONS                  *
     ***************************************************/

    /**
     * @notice Configure a controller with the given worker
     * @dev The worker must be a non-zero address. To disable a controller, use
     * removeController instead.
     * @param controller The controller to be configured with a worker
     * @param worker The worker to be set for the controller
     */
    function configureController(address controller, address worker) public onlyOwner {
        if (controller == address(0)) {
            revert ControllerZeroAddress();
        }
        if (worker == address(0)) {
            revert WorkerZeroAddress();
        }

        controllers.set(controller, worker);
        emit ControllerConfigured(controller, worker);
    }

    /**
     * @notice Disables a controller by removing it from the enumerable map
     * @dev WARNING: A worker can be managed by multiple controllers. Removing one
     * controller does not affect the worker's status if it remains managed by at
     * least one other controller.
     * @param controller The controller to disable
     */
    function removeController(address controller) public onlyOwner {
        if (controller == address(0)) {
            revert ControllerZeroAddress();
        }
        if (!controllers.contains(controller)) {
            revert ControllerNotFound(controller);
        }

        controllers.remove(controller);
        emit ControllerRemoved(controller);
    }
}

contracts/minting/MasterMinter.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { MintController } from "./MintController.sol";

/**
 * @title MasterMinter
 * @notice MasterMinter uses multiple controllers to manage minters for a contract
 *         that implements the IMinterManagement interface
 * @dev MasterMinter inherits all its functionality from MintController.
 *      This provides a clean separation of concerns:
 *      - Owner (typically a multisig or governance contract) manages controllers
 *      - Controllers (typically EOAs or automated systems) manage individual minters
 *      - Minters (typically bridge contracts) mint tokens within their allowances
 *
 *      This is a modernized version of USDC's MasterMinter contract.
 */
contract MasterMinter is MintController {
    /**
     * @notice Initializes the MasterMinter with a minter manager and owner
     * @param minterManager The address of the minter manager contract (typically the token contract)
     * @param owner The address of the owner (typically a multisig or governance contract)
     */
    constructor(address minterManager, address owner) MintController(minterManager, owner) {}
}

contracts/minting/MintController.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity 0.8.28;

import { Controller } from "./Controller.sol";
import { IMinterManagement } from "../interfaces/IMinterManagement.sol";

/**
 * @title MintController
 * @notice Manages minters for a contract that implements the IMinterManagement interface
 * @dev The MintController contract lets the owner designate certain addresses as controllers,
 *      and these controllers then manage the minters by adding and removing minters, as well as
 *      modifying their minting allowance. A controller may manage exactly one minter, but the same
 *      minter address may be managed by multiple controllers.
 *
 *      MintController inherits from the Controller contract. It treats the Controller workers as minters.
 *      This is a modernized version of USDC's MintController contract using custom errors and Solidity ^0.8.0
 */
contract MintController is Controller {
    /***************************************************
     *                   STORAGE                       *
     ***************************************************/

    /**
     * @dev MintController calls the minterManager to execute/record minter
     * management tasks, as well as to query the status of a minter address.
     */
    IMinterManagement internal minterManager;

    /**
     * @dev Maximum allowance that each controller can assign to its minter.
     *      When configureController is called, defaults to 0 (zero-only controller).
     *      Owner must explicitly set ceiling via setControllerCeiling.
     *      Special value: type(uint256).max means unlimited.
     */
    mapping(address controller => uint256 ceiling) internal controllerCeilings;

    /***************************************************
     *                    EVENTS                       *
     ***************************************************/

    /**
     * @notice Emitted when the minter manager is updated
     * @param oldMinterManager The address of the old minter manager
     * @param newMinterManager The address of the new minter manager
     */
    event MinterManagerSet(address indexed oldMinterManager, address indexed newMinterManager);

    /**
     * @notice Emitted when a minter is configured by a controller
     * @param controller The address of the controller
     * @param minter The address of the minter
     * @param allowance The new allowance for the minter
     */
    event MinterConfigured(address indexed controller, address indexed minter, uint256 allowance);

    /**
     * @notice Emitted when a minter is removed by a controller
     * @param controller The address of the controller
     * @param minter The address of the minter
     */
    event MinterRemoved(address indexed controller, address indexed minter);

    /**
     * @notice Emitted when a minter's allowance is incremented
     * @param controller The address of the controller
     * @param minter The address of the minter
     * @param increment The amount the allowance was incremented by
     * @param newAllowance The new total allowance
     */
    event MinterAllowanceIncremented(
        address indexed controller,
        address indexed minter,
        uint256 increment,
        uint256 newAllowance
    );

    /**
     * @notice Emitted when a minter's allowance is decremented
     * @param controller The address of the controller
     * @param minter The address of the minter
     * @param decrement The amount the allowance was decremented by
     * @param newAllowance The new total allowance
     */
    event MinterAllowanceDecremented(
        address indexed controller,
        address indexed minter,
        uint256 decrement,
        uint256 newAllowance
    );

    /**
     * @notice Emitted when a controller's allowance ceiling is updated
     * @param controller The address of the controller
     * @param ceiling The new ceiling value (type(uint256).max means unlimited)
     */
    event ControllerCeilingUpdated(address indexed controller, uint256 ceiling);

    /***************************************************
     *                    ERRORS                       *
     ***************************************************/

    /**
     * @notice Thrown when the minter manager address is zero
     */
    error MinterManagerZeroAddress();

    /**
     * @notice Thrown when trying to increment allowance by zero
     */
    error AllowanceIncrementZero();

    /**
     * @notice Thrown when trying to decrement allowance by zero
     */
    error AllowanceDecrementZero();

    /**
     * @notice Thrown when trying to increment/decrement allowance for an inactive minter
     * @param minter The minter address that is not active
     */
    error MinterNotActive(address minter);

    /**
     * @notice Thrown when trying to set an allowance that exceeds the controller's ceiling
     * @param requestedAllowance The allowance that was requested
     * @param ceiling The maximum allowed ceiling for this controller
     */
    error AllowanceExceedsCeiling(uint256 requestedAllowance, uint256 ceiling);

    /***************************************************
     *                CONSTRUCTOR                      *
     ***************************************************/

    /**
     * @notice Initializes the MintController with a minter manager and owner
     * @dev Can be deployed with address(0) for minterManager to support atomic deployment
     *      where MasterMinter is deployed before the token. In this case, setMinterManager()
     *      must be called before any controller functions can be used.
     * @param minterManager_ The address of the minter manager contract (can be address(0))
     * @param owner The address of the owner
     */
    constructor(address minterManager_, address owner) Controller(owner) {
        // Allow address(0) for deployment flexibility
        // If deployed with address(0), setMinterManager() must be called before use
        if (minterManager_ != address(0)) {
            minterManager = IMinterManagement(minterManager_);
        }
    }

    /***************************************************
     *              VIEW FUNCTIONS                     *
     ***************************************************/

    /**
     * @notice Gets the minter manager
     * @return The minter manager contract
     */
    function getMinterManager() external view returns (IMinterManagement) {
        return minterManager;
    }

    /**
     * @notice Gets the allowance ceiling for a controller
     * @param controller The address of the controller
     * @return The ceiling value (type(uint256).max means unlimited)
     */
    function getControllerCeiling(address controller) external view returns (uint256) {
        return controllerCeilings[controller];
    }

    /***************************************************
     *           ONLY OWNER FUNCTIONS                  *
     ***************************************************/

    /**
     * @notice Sets the minter manager
     * @dev This function serves two purposes:
     *      1. Initial setup: If deployed with address(0), this sets the minter manager for the first time
     *      2. Migration: Allows changing to a new token contract if needed
     * @param newMinterManager The address of the new minter manager contract
     */
    function setMinterManager(address newMinterManager) public onlyOwner {
        if (newMinterManager == address(0)) {
            revert MinterManagerZeroAddress();
        }

        emit MinterManagerSet(address(minterManager), newMinterManager);
        minterManager = IMinterManagement(newMinterManager);
    }

    /**
     * @notice Configure a controller with the given worker (minter) and allowance ceiling
     * @dev Extends configureController from parent to also set the allowance ceiling.
     *      Ceiling values:
     *      - 0: Controller can only set allowance to 0 (can only disable minters)
     *      - Any value > 0 and < max: Maximum allowance the controller can assign
     *      - type(uint256).max: Unlimited
     * @param controller The controller to be configured with a worker
     * @param worker The worker (minter) to be set for the controller
     * @param ceiling The maximum allowance the controller can assign
     */
    function configureControllerWithCeiling(address controller, address worker, uint256 ceiling) public onlyOwner {
        // Call parent to configure controller-worker mapping
        configureController(controller, worker);

        // Set the ceiling
        controllerCeilings[controller] = ceiling;
        emit ControllerCeilingUpdated(controller, ceiling);
    }

    /**
     * @notice Sets the allowance ceiling for a controller
     * @dev Ceiling values:
     *      - 0: Controller can only set allowance to 0 (can only disable minters)
     *      - Any value > 0 and < max: Maximum allowance the controller can assign
     *      - type(uint256).max: Unlimited
     *      Only the owner can set controller ceilings.
     * @param controller The address of the controller
     * @param ceiling The maximum allowance the controller can assign
     */
    function setControllerCeiling(address controller, uint256 ceiling) public onlyOwner {
        controllerCeilings[controller] = ceiling;
        emit ControllerCeilingUpdated(controller, ceiling);
    }

    /***************************************************
     *         ONLY CONTROLLER FUNCTIONS               *
     ***************************************************/

    /**
     * @notice Removes the controller's own minter
     * @dev Can only be called by an active controller
     */
    function removeMinter() public onlyController {
        address minter = _getWorker(msg.sender);
        emit MinterRemoved(msg.sender, minter);
        minterManager.removeMinter(minter);
    }

    /**
     * @notice Enables the minter and sets its allowance
     * @dev Can only be called by an active controller
     * @param newAllowance New allowance to be set for minter
     */
    function configureMinter(uint256 newAllowance) public onlyController {
        _validateAllowanceCeiling(msg.sender, newAllowance);
        address minter = _getWorker(msg.sender);
        emit MinterConfigured(msg.sender, minter, newAllowance);
        _setMinterAllowance(minter, newAllowance);
    }

    /**
     * @notice Increases the minter's allowance if and only if the minter is an active minter
     * @dev A minter is considered active if minterManager.isMinter(minter) returns true.
     *      Can only be called by an active controller.
     * @param allowanceIncrement The amount to increment the allowance by
     */
    function incrementMinterAllowance(uint256 allowanceIncrement) public onlyController {
        if (allowanceIncrement == 0) {
            revert AllowanceIncrementZero();
        }

        address minter = _getWorker(msg.sender);
        if (!minterManager.isMinter(minter)) {
            revert MinterNotActive(minter);
        }

        uint256 currentAllowance = minterManager.minterAllowance(minter);
        uint256 newAllowance = currentAllowance + allowanceIncrement;

        _validateAllowanceCeiling(msg.sender, newAllowance);

        emit MinterAllowanceIncremented(msg.sender, minter, allowanceIncrement, newAllowance);
        _setMinterAllowance(minter, newAllowance);
    }

    /**
     * @notice Decreases the minter's allowance if and only if the minter is currently active
     * @dev The controller can safely send a signed decrementMinterAllowance() transaction to a minter
     *      and not worry about it being used to undo a removeMinter() transaction.
     *      If the decrement is greater than the current allowance, the allowance is set to 0.
     *      Can only be called by an active controller.
     * @param allowanceDecrement The amount to decrement the allowance by
     */
    function decrementMinterAllowance(uint256 allowanceDecrement) public onlyController {
        if (allowanceDecrement == 0) {
            revert AllowanceDecrementZero();
        }

        address minter = _getWorker(msg.sender);
        if (!minterManager.isMinter(minter)) {
            revert MinterNotActive(minter);
        }

        uint256 currentAllowance = minterManager.minterAllowance(minter);
        uint256 actualAllowanceDecrement = currentAllowance > allowanceDecrement
            ? allowanceDecrement
            : currentAllowance;
        uint256 newAllowance = currentAllowance - actualAllowanceDecrement;

        emit MinterAllowanceDecremented(msg.sender, minter, actualAllowanceDecrement, newAllowance);
        _setMinterAllowance(minter, newAllowance);
    }

    /***************************************************
     *           INTERNAL FUNCTIONS                    *
     ***************************************************/

    /**
     * @notice Validates that the requested allowance does not exceed the controller's ceiling
     * @dev Ceiling of type(uint256).max represents unlimited allowance (no validation).
     * For any other ceiling value, the function enforces that newAllowance <= ceiling.
     * Reverts with AllowanceExceedsCeiling if the limit is exceeded.
     * @param controller The controller address to check
     * @param newAllowance The allowance to validate
     */
    function _validateAllowanceCeiling(address controller, uint256 newAllowance) internal view {
        uint256 ceiling = controllerCeilings[controller];

        // Max ceiling means unlimited, no validation needed
        if (ceiling == type(uint256).max) {
            return;
        }

        // Enforce ceiling
        if (newAllowance > ceiling) {
            revert AllowanceExceedsCeiling(newAllowance, ceiling);
        }
    }

    /**
     * @notice Uses the IMinterManagement interface to enable the minter and set its allowance
     * @param minter Minter to set new allowance of
     * @param newAllowance New allowance to be set for minter
     */
    function _setMinterAllowance(address minter, uint256 newAllowance) internal {
        minterManager.configureMinter(minter, newAllowance);
    }
}

